import React, { useState } from 'react';

/**
 * CodeSnippets - Dropdown with pre-built code templates
 */
const CodeSnippets = ({ onCodeSelect, isDarkMode }) => {
  const [isOpen, setIsOpen] = useState(false);
  
  // Pre-defined code snippets
  const snippets = [
    {
      name: '📝 Hello World',
      code: `start {
    say "Hello, World!"
    say "Welcome to EVENTRA!"
}`
    },
    {
      name: '🎯 Event Handler Template',
      code: `start {
    say "Program started!"
}

on click {
    say "Button clicked!"
}

on login {
    say "User logged in"
}`
    },
    {
      name: '📥 Input/Output Example',
      code: `start {
    say "What is your name?"
    input name
    say "Hello, " + name
    say "How old are you?"
    input age
    say "You are " + age + " years old"
}`
    },
    {
      name: '💬 Comments Demo',
      code: `# This is a comment
start {
    # Initialize greeting
    say "Hello!"  # Inline comment
    
    # Another comment
    say "Welcome!"
}`
    },
    {
      name: '🎮 Multi-Event Program',
      code: `start {
    say "Game Started!"
    say "Choose your action:"
}

on attack {
    say "Attacking enemy..."
    say "Enemy defeated!"
}

on defend {
    say "Raising shield..."
    say "Damage reduced!"
}

on heal {
    say "Healing..."
    say "Health restored!"
}

on inventory {
    say "Opening inventory..."
    say "You have: Sword, Shield, Potion"
}`
    },
    {
      name: '🤖 Chat Bot Template',
      code: `start {
    say "Bot: Hello! I am EVENTRA Bot"
    say "Bot: What is your name?"
    input name
    say "Bot: Nice to meet you"
    say name
}

on joke {
    say "Bot: Why did the programmer quit his job?"
    say "Bot: Because he did not get arrays!"
    say "Bot: Haha!"
}

on help {
    say "Bot: I can tell jokes or chat with you!"
}

on bye {
    say "Bot: Goodbye"
    say name
    say "Bot: Have a great day!"
}`
    },
    {
      name: '📊 Quiz Template',
      code: `start {
    say "QUIZ TIME!"
    say "============="
    say "Question 1: What is the capital of France?"
    input answer1
    say "Question 2: What is 5 + 3?"
    input answer2
    say "Your Answers:"
    say answer1
    say answer2
}`
    },
    {
      name: '🌤️ Weather App Mockup',
      code: `start {
    say "WEATHER APP"
    say "============="
    say "Enter city name:"
    input city
    say "Fetching weather for"
    say city
    say "Weather Information:"
    say "City"
    say city
    say "Temperature: 25C"
    say "Condition: Sunny"
}`
    }
  ];
  
  const handleSelect = (snippet) => {
    onCodeSelect(snippet.code);
    setIsOpen(false);
  };
  
  return (
    <div style={{
      position: 'relative',
      display: 'inline-block'
    }}>
      {/* Dropdown Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        style={{
          padding: '0.75rem 1.5rem',
          fontSize: '1rem',
          fontWeight: '600',
          backgroundColor: isDarkMode ? '#4a4a6a' : '#e0e0e0',
          color: isDarkMode ? '#ffffff' : '#1a1a2e',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          transition: 'all 0.3s ease'
        }}
      >
        📚 Snippets {isOpen ? '▲' : '▼'}
      </button>
      
      {/* Dropdown Menu */}
      {isOpen && (
        <div style={{
          position: 'absolute',
          top: '100%',
          left: 0,
          marginTop: '0.5rem',
          backgroundColor: isDarkMode ? '#2d2d44' : '#ffffff',
          border: `2px solid ${isDarkMode ? '#4a4a6a' : '#cccccc'}`,
          borderRadius: '8px',
          boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
          zIndex: 1000,
          minWidth: '250px',
          maxHeight: '400px',
          overflowY: 'auto'
        }}>
          {snippets.map((snippet, index) => (
            <button
              key={index}
              onClick={() => handleSelect(snippet)}
              style={{
                display: 'block',
                width: '100%',
                padding: '0.75rem 1rem',
                textAlign: 'left',
                backgroundColor: 'transparent',
                border: 'none',
                borderBottom: `1px solid ${isDarkMode ? '#3d3d5c' : '#f0f0f0'}`,
                color: isDarkMode ? '#ffffff' : '#1a1a2e',
                cursor: 'pointer',
                transition: 'background-color 0.2s',
                fontSize: '0.95rem'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = isDarkMode ? '#3d3d5c' : '#f0f0f0';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = 'transparent';
              }}
            >
              {snippet.name}
            </button>
          ))}
        </div>
      )}
      
      {/* Click outside to close */}
      {isOpen && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 999
          }}
          onClick={() => setIsOpen(false)}
        />
      )}
    </div>
  );
};

export default CodeSnippets;
